// A scroll view lays its document out from the bottom unless the view is
// flipped, which stacks settings cards upward from the foot of the pane.
@interface PebbleFlippedView : NSView
@end

@implementation PebbleFlippedView
- (BOOL)isFlipped {
    return YES;
}
@end

// NSBox manages its content view by autoresizing, which breaks the constraint
// chain a stack of cards needs to report its own height. Drawing the rounded
// background here keeps everything in autolayout.
@interface PebbleRoundedView : NSView
@property (nonatomic, strong) NSColor *fill;
@property (nonatomic, strong) NSColor *stroke;
@property CGFloat radius;
@end

@implementation PebbleRoundedView
- (void)drawRect:(NSRect)rect {
    if (self.fill && self.fill != NSColor.clearColor) {
        [self.fill setFill];
        [[NSBezierPath bezierPathWithRoundedRect:self.bounds
                                         xRadius:self.radius yRadius:self.radius] fill];
    }
    if (!self.stroke) return;
    NSBezierPath *edge = [NSBezierPath bezierPathWithRoundedRect:NSInsetRect(self.bounds, .5, .5)
                                                        xRadius:self.radius yRadius:self.radius];
    edge.lineWidth = 1;
    [self.stroke setStroke];
    [edge stroke];
}
- (void)setFill:(NSColor *)fill {
    _fill = fill;
    self.needsDisplay = YES;
}
@end

