@implementation PebbleApp

- (void)applicationDidFinishLaunching:(NSNotification *)notification {
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    self.paused = [defaults boolForKey:PausedPreference];
    self.pebbleHistory = [[defaults dictionaryForKey:PebbleHistoryKey] mutableCopy] ?: [NSMutableDictionary dictionary];
    self.favorites = [[defaults arrayForKey:PebbleFavoritesKey] mutableCopy] ?: [NSMutableArray array];
    self.tiltDegrees = MAX(-TiltLimit, MIN(TiltLimit, [defaults integerForKey:TiltPreference]));
    self.rotationRate = 1;
    double savedRate = [defaults doubleForKey:SpeedPreference];
    for (NSUInteger i = 0; i < sizeof(RotationRates) / sizeof(RotationRates[0]); i++) {
        if (savedRate == RotationRates[i]) self.rotationRate = savedRate;
    }
    self.face = [self known:[NSUserDefaults.standardUserDefaults stringForKey:FacePreference]
                         in:PebbleFaceKeys count:PebbleFaceCount];
    self.texture = [self known:[NSUserDefaults.standardUserDefaults stringForKey:TexturePreference]
                            in:PebbleTextureKeys count:PebbleTextureCount];
    self.palette = [self known:[NSUserDefaults.standardUserDefaults stringForKey:PalettePreference]
                            in:PebbleColorKeys count:PebbleColorCount];
    self.backgroundPreset = [self known:[NSUserDefaults.standardUserDefaults stringForKey:BackgroundPreference]
                                       in:BackgroundKeys count:BackgroundCount] ?: @"paper";
    self.desktopWindows = [NSMutableDictionary dictionary];
    self.desktopControls = [NSMutableDictionary dictionary];
    self.rendererRecovery = [NSMapTable weakToStrongObjectsMapTable];
    self.statusItem = [NSStatusBar.systemStatusBar statusItemWithLength:NSVariableStatusItemLength];
    self.statusItem.button.image = PebbleMenuBarIcon();
    self.statusItem.button.toolTip = WallpaperTitle;

    NSMenu *menu = [[NSMenu alloc] initWithTitle:WallpaperTitle];
    NSMenuItem *rethrow = [menu addItemWithTitle:@"重新抛" action:nil keyEquivalent:@""];
    self.rethrowMenu = [[NSMenu alloc] initWithTitle:rethrow.title];
    rethrow.submenu = self.rethrowMenu;
    [self addItem:@"上一颗" action:@selector(previousPebble:) toMenu:menu];
    [self addChoiceMenusTo:menu];
    self.pauseItem = [self addItem:@"旋转开关" action:@selector(togglePause:) toMenu:menu];
    // Reads as a switch now, so the tick means spinning rather than stopped. The
    // stored preference stays WallpaperPaused so existing choices survive.
    self.pauseItem.state = self.paused ? NSControlStateValueOff : NSControlStateValueOn;
    NSMenuItem *smart = [self addItem:@"智能暂停" action:@selector(toggleSmartPause:) toMenu:menu];
    smart.state = [NSUserDefaults.standardUserDefaults boolForKey:SmartPauseDisabledKey] ? NSControlStateValueOff : NSControlStateValueOn;
    [self addMotionMenusTo:menu];
    NSMenuItem *wallpaper = [menu addItemWithTitle:@"静态壁纸" action:nil keyEquivalent:@""];
    wallpaper.submenu = [[NSMenu alloc] initWithTitle:wallpaper.title];
    NSMenuItem *export = [wallpaper.submenu addItemWithTitle:@"导出 PNG" action:nil keyEquivalent:@""];
    export.submenu = [[NSMenu alloc] initWithTitle:export.title];
    for (NSUInteger index = 0; index < WallpaperSizeCount; index++) {
        WallpaperExportSize size = WallpaperSizes[index];
        NSString *title = [NSString stringWithFormat:@"%@（%lu × %lu）…", size.name,
                           (unsigned long)size.width, (unsigned long)size.height];
        [self addItem:title action:@selector(exportWallpaper:) toMenu:export.submenu].tag = index;
    }
    [self addItem:@"设为静态壁纸" action:@selector(setStaticWallpaper:) toMenu:wallpaper.submenu];
    [self addItem:@"恢复动态壁纸" action:@selector(resumeDynamicWallpaper:) toMenu:wallpaper.submenu];
    [self addItem:@"恢复壁纸显示" action:@selector(reloadRenderers:) toMenu:menu];
    NSMenuItem *settingsItem = [self addItem:@"设置…" action:@selector(showSettings:) toMenu:menu];
    settingsItem.keyEquivalent = @",";
    [menu addItem:NSMenuItem.separatorItem];
#if __has_include(<Sparkle/Sparkle.h>)
    if (!self.testPreviewPath && !self.shotPath) {
        self.updaterController = [[SPUStandardUpdaterController alloc]
            initWithStartingUpdater:YES updaterDelegate:self userDriverDelegate:nil];
        NSMenuItem *updateItem = [menu addItemWithTitle:@"检查更新…"
            action:@selector(checkForUpdates:) keyEquivalent:@""];
        updateItem.target = self.updaterController;
#ifdef PEBBLE_UPDATE_TEST
        if ([NSProcessInfo.processInfo.arguments containsObject:@"--check-for-updates"]) {
            self.updaterController.updater.automaticallyDownloadsUpdates = YES;
            [self.updaterController.updater checkForUpdatesInBackground];
        }
#endif
    }
#endif
    [self addItem:@"退出鹅卵石" action:@selector(quit:) toMenu:menu];
    self.statusItem.menu = menu;
    // Renders a settings pane straight to PNG. The window's layout cannot be
    // checked any other way, and screen capture needs permissions a build box
    // will not have. Same kind of affordance as --verify.
    if (self.shotPath) {
        [self showSettings:nil];
        [self showPaneAtIndex:self.shotSection];
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 2200 * NSEC_PER_MSEC),
                       dispatch_get_main_queue(), ^{
            if (self.shotSection == PassPaneIndex) {
                [self capturePassForVerification];
                return;
            }
            NSView *view = self.settings.contentView;
            NSBitmapImageRep *rep = [view bitmapImageRepForCachingDisplayInRect:view.bounds];
            [view cacheDisplayInRect:view.bounds toBitmapImageRep:rep];
            [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]
                writeToFile:self.shotPath atomically:YES];
            [NSApp terminate:nil];
        });
        return;
    }
    if (!self.testPreviewPath) [self observeSmartPause];
    [self refreshDisplays:nil];
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(refreshDisplays:)
                 name:NSApplicationDidChangeScreenParametersNotification object:NSApp];
}

#if __has_include(<Sparkle/Sparkle.h>)
- (BOOL)updater:(SPUUpdater *)updater willInstallUpdateOnQuit:(SUAppcastItem *)item
    immediateInstallationBlock:(void (^)(void))install {
#ifdef PEBBLE_UPDATE_TEST
    // Logged so the loopback harness can assert against the same path production takes.
    NSLog(@"Verified update %@ ready to install.", item.versionString);
#endif
    // The wallpaper is a login agent that users never quit, so waiting for
    // termination could strand them on an old build for weeks. Install right
    // away instead; Sparkle relaunches the wallpaper with no interface shown.
    [self stageUpdateInstallation:install];
    return YES;
}

- (void)stageUpdateInstallation:(void (^)(void))install {
    self.pendingInstall = install;
    self.installationRequested = NO;
#ifdef PEBBLE_UPDATE_TEST
    if ([NSProcessInfo.processInfo.arguments containsObject:@"--defer-update-test"]) {
        [self showSettings:nil];
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 2 * NSEC_PER_SEC),
                       dispatch_get_main_queue(), ^{
            if (self.installationRequested || !self.pendingInstall) exit(11);
            NSLog(@"Update deferred while settings are open; closing settings now.");
            [self.settings close];
        });
    }
#endif
    // Sparkle may only use the handler after this delegate has returned YES.
    dispatch_async(dispatch_get_main_queue(), ^{ [self installPendingUpdateIfIdle]; });
}

// Relaunching while the interactive window is open would discard it mid-use.
- (void)installPendingUpdateIfIdle {
    if (!self.pendingInstall || self.installationRequested || self.settings.isVisible) return;
    self.installationRequested = YES;
    void (^install)(void) = self.pendingInstall;
    install();
    // An application or system service can cancel termination. Keep the handler
    // so closing settings or the next idle opportunity can retry, without looping.
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 5 * NSEC_PER_SEC),
                   dispatch_get_main_queue(), ^{
        if (self.pendingInstall == install) self.installationRequested = NO;
    });
}

- (void)resetPendingUpdate {
    self.pendingInstall = nil;
    self.installationRequested = NO;
}

- (void)updater:(SPUUpdater *)updater didAbortWithError:(NSError *)error {
    [self resetPendingUpdate];
    NSLog(@"Update aborted: %@", error);
}
- (void)updater:(SPUUpdater *)updater didFinishUpdateCycleForUpdateCheck:(SPUUpdateCheck)check
    error:(NSError *)error {
    [self resetPendingUpdate];
}

- (void)settingsDidClose:(NSNotification *)notification {
    // NSWindowWillClose arrives before isVisible changes.
    dispatch_async(dispatch_get_main_queue(), ^{ [self installPendingUpdateIfIdle]; });
}
#endif

- (NSMenuItem *)addItem:(NSString *)title action:(SEL)action toMenu:(NSMenu *)menu {
    NSMenuItem *item = [menu addItemWithTitle:title action:action keyEquivalent:@""];
    item.target = self;
    return item;
}

// Anything outside the generated tables names something the renderer cannot
// draw, and an unknown key would quietly fall back to a plain random stone.
- (NSString *)known:(NSString *)candidate in:(const char *const *)keys count:(NSUInteger)count {
    for (NSUInteger index = 0; index < count; index++) {
        if ([candidate isEqualToString:@(keys[index])]) return candidate;
    }
    return nil;
}

- (NSMenu *)addChoicesTitled:(NSString *)title keys:(const char *const *)keys
                      labels:(const char *const *)labels count:(NSUInteger)count
                      action:(SEL)action toMenu:(NSMenu *)menu {
    NSMenu *choices = [[NSMenu alloc] initWithTitle:title];
    [self addItem:@"随机" action:action toMenu:choices].representedObject = @"";
    [choices addItem:NSMenuItem.separatorItem];
    for (NSUInteger index = 0; index < count; index++) {
        [self addItem:@(labels[index]) action:action toMenu:choices]
            .representedObject = @(keys[index]);
    }
    [menu addItemWithTitle:title action:nil keyEquivalent:@""].submenu = choices;
    return choices;
}

- (void)addChoiceMenusTo:(NSMenu *)menu {
    self.textureMenu = [self addChoicesTitled:@"鹅卵石材质" keys:PebbleTextureKeys
                                       labels:PebbleTextureLabels count:PebbleTextureCount
                                       action:@selector(selectTexture:) toMenu:menu];
    self.paletteMenu = [self addChoicesTitled:@"鹅卵石颜色" keys:PebbleColorKeys
                                       labels:PebbleColorLabels count:PebbleColorCount
                                       action:@selector(selectPalette:) toMenu:menu];
    self.faceMenu = [self addChoicesTitled:@"鹅卵石脸孔" keys:PebbleFaceKeys
                                    labels:PebbleFaceLabels count:PebbleFaceCount
                                    action:@selector(selectFace:) toMenu:menu];
    [self mark:self.texture inMenu:self.textureMenu];
    [self mark:self.palette inMenu:self.paletteMenu];
    [self mark:self.face inMenu:self.faceMenu];
}

- (void)mark:(NSString *)selected inMenu:(NSMenu *)menu {
    for (NSMenuItem *item in menu.itemArray) {
        if (!item.representedObject) continue;
        item.state = [item.representedObject isEqualToString:selected ?: @""] ?
            NSControlStateValueOn : NSControlStateValueOff;
    }
}

- (NSString *)tiltTitle:(NSInteger)degrees {
    return degrees == 0 ? @"0°" : [NSString stringWithFormat:@"%+ld°", (long)degrees];
}

- (NSString *)rateTitle:(double)rate {
    return [NSString stringWithFormat:@"%g×", rate];
}

- (void)addMotionMenusTo:(NSMenu *)menu {
    self.tiltMenu = [[NSMenu alloc] initWithTitle:@"倾斜角度"];
    for (NSUInteger i = 0; i < sizeof(TiltPresets) / sizeof(TiltPresets[0]); i++) {
        NSInteger degrees = TiltPresets[i];
        [self addItem:[self tiltTitle:degrees] action:@selector(selectTilt:) toMenu:self.tiltMenu]
            .representedObject = @(degrees);
    }
    [self.tiltMenu addItem:NSMenuItem.separatorItem];
    [self addItem:@"自定…" action:@selector(showTiltSettings:) toMenu:self.tiltMenu];
    [menu addItemWithTitle:@"倾斜角度" action:nil keyEquivalent:@""].submenu = self.tiltMenu;

    self.speedMenu = [[NSMenu alloc] initWithTitle:@"旋转速度"];
    for (NSUInteger i = 0; i < sizeof(RotationRates) / sizeof(RotationRates[0]); i++) {
        double rate = RotationRates[i];
        [self addItem:[self rateTitle:rate] action:@selector(selectRotationRate:) toMenu:self.speedMenu]
            .representedObject = @(rate);
    }
    [menu addItemWithTitle:@"旋转速度" action:nil keyEquivalent:@""].submenu = self.speedMenu;
    [self syncMotionControls];
}

- (void)showTiltSettings:(id)sender {
    [self showSettings:nil];
    [self showPaneAtIndex:0];
    [self.settings makeFirstResponder:self.tiltSlider];
}

- (void)syncMotionControls {
    NSString *tilt = [self tiltTitle:self.tiltDegrees];
    self.tiltSlider.integerValue = self.tiltDegrees;
    self.tiltValue.stringValue = tilt;
    [self.speedPicker selectItemWithTitle:[self rateTitle:self.rotationRate]];
    for (NSMenuItem *item in self.tiltMenu.supermenu.itemArray) {
        if (item.submenu == self.tiltMenu) item.title = [@"倾斜角度  " stringByAppendingString:tilt];
    }
    for (NSMenuItem *item in self.tiltMenu.itemArray) {
        if (item.representedObject) item.state = [item.representedObject isEqual:@(self.tiltDegrees)];
    }
    for (NSMenuItem *item in self.speedMenu.itemArray) {
        item.state = [item.representedObject isEqual:@(self.rotationRate)];
    }
}

- (NSString *)motionConfigScript {
    return [NSString stringWithFormat:@"window.pebbleConfig = window.pebbleConfig || {};"
            "window.pebbleConfig.tiltDegrees = %ld; window.pebbleConfig.rotationRate = %.1f;",
            (long)self.tiltDegrees, self.rotationRate];
}

- (void)updateMotionRenderers:(BOOL)restartTimer {
    NSString *update = restartTimer
        ? @"document.dispatchEvent(new Event('visibilitychange'));" : @"window.pebbleRedraw?.();";
    NSString *script = [self.motionConfigScript stringByAppendingString:update];
    [self forEachRenderer:^(WKWebView *web) {
        [web evaluateJavaScript:script completionHandler:nil];
    }];
}

- (void)selectTilt:(id)sender {
    NSInteger degrees = [sender isKindOfClass:NSSlider.class]
        ? [sender integerValue] : [[sender representedObject] integerValue];
    self.tiltDegrees = MAX(-TiltLimit, MIN(TiltLimit, degrees));
    [NSUserDefaults.standardUserDefaults setInteger:self.tiltDegrees forKey:TiltPreference];
    [self syncMotionControls];
    [self updateMotionRenderers:NO];
}

- (void)selectRotationRate:(id)sender {
    NSMenuItem *item = [sender isKindOfClass:NSPopUpButton.class] ? [sender selectedItem] : sender;
    self.rotationRate = [item.representedObject doubleValue];
    [NSUserDefaults.standardUserDefaults setDouble:self.rotationRate forKey:SpeedPreference];
    [self syncMotionControls];
    [self updateMotionRenderers:YES];
}

- (NSString *)backgroundConfigScript {
    NSUInteger index = 0;
    while (index + 1 < BackgroundCount && ![self.backgroundPreset isEqualToString:@(BackgroundKeys[index])]) index++;
    return [NSString stringWithFormat:
        @"document.documentElement.dataset.pebbleBackground = '%@';"
         "document.documentElement.style.setProperty('--wallpaper-background', '#%06lX');",
        self.backgroundPreset, (unsigned long)BackgroundColors[index]];
}

- (NSString *)rendererConfigScript {
    // Both keys come from the generated tables, so they are plain identifiers.
    NSString *texture = self.texture ? [NSString stringWithFormat:@"'%@'", self.texture] : @"null";
    NSString *palette = self.palette ? [NSString stringWithFormat:@"'%@'", self.palette] : @"null";
    return [NSString stringWithFormat:@"window.pebbleConfig = window.pebbleConfig || {};"
            "window.pebbleConfig.texture = %@; window.pebbleConfig.palette = %@;"
            "window.pebbleConfig.faces = %@;"
            "%@%@",
            texture, palette,
            self.face ? [NSString stringWithFormat:@"'%@'", self.face] : @"null",
            self.backgroundConfigScript, self.motionConfigScript];
}

- (void)storeChoice:(NSString *)choice forKey:(NSString *)key {
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    if (choice) {
        [defaults setObject:choice forKey:key];
    } else {
        [defaults removeObjectForKey:key];
    }
    [self syncSettingsControls];
    [self forEachRenderer:^(WKWebView *web) {
        [web evaluateJavaScript:self.rendererConfigScript completionHandler:nil];
    }];
    // The stone already on screen keeps whatever it was raised with.
    [self changePebble:nil];
}

- (void)selectFace:(id)sender {
    self.face = [self known:[self choiceFrom:sender] in:PebbleFaceKeys count:PebbleFaceCount];
    [self mark:self.face inMenu:self.faceMenu];
    [self storeChoice:self.face forKey:FacePreference];
}

- (NSString *)choiceFrom:(id)sender {
    NSMenuItem *item = [sender isKindOfClass:NSPopUpButton.class] ?
        ((NSPopUpButton *)sender).selectedItem : sender;
    return item.representedObject;
}

- (void)selectTexture:(id)sender {
    self.texture = [self known:[self choiceFrom:sender]
                            in:PebbleTextureKeys count:PebbleTextureCount];
    [self mark:self.texture inMenu:self.textureMenu];
    [self storeChoice:self.texture forKey:TexturePreference];
}

- (void)selectPalette:(id)sender {
    self.palette = [self known:[self choiceFrom:sender]
                            in:PebbleColorKeys count:PebbleColorCount];
    [self mark:self.palette inMenu:self.paletteMenu];
    [self storeChoice:self.palette forKey:PalettePreference];
}

- (WKWebView *)newRendererForDesktop:(BOOL)desktop {
    return [self newRendererWithConfig:self.rendererConfigScript desktop:desktop];
}

- (WKWebView *)newRendererWithConfig:(NSString *)config desktop:(BOOL)desktop {
    WKWebViewConfiguration *configuration = [WKWebViewConfiguration new];
    configuration.websiteDataStore = WKWebsiteDataStore.nonPersistentDataStore;
    // The first pebble is raised while the module loads, so the choice has to be
    // in place before any of the bundle runs.
    [configuration.userContentController addUserScript:[[WKUserScript alloc]
        initWithSource:config
         injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:YES]];
    if (desktop) {
        WKUserScript *showQuestion = [[WKUserScript alloc]
            initWithSource:@"document.documentElement.classList.add('pebble-desktop')"
             injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:YES];
        [configuration.userContentController addUserScript:showQuestion];
        [configuration.userContentController addScriptMessageHandler:self name:PebbleToneMessage];
        [configuration.userContentController addScriptMessageHandler:self name:@"pebbleHistory"];
    }
    WKWebView *web = [[WKWebView alloc] initWithFrame:NSZeroRect configuration:configuration];
    [self.rendererRecovery setObject:[PebbleRendererRecovery new] forKey:web];
    web.navigationDelegate = self;
    NSURL *page = [NSBundle.mainBundle URLForResource:@"wallpaper" withExtension:@"html"];
    [web loadFileURL:page allowingReadAccessToURL:page];
    return web;
}

- (void)placeDesktopControlOnScreen:(NSScreen *)screen display:(NSNumber *)display {
    NSRect screenFrame = screen.frame;
    // Match the question's desktop CSS and align the button with the end of the last line.
    CGFloat questionWidth = MIN(226, NSWidth(screenFrame) * .30);
    CGFloat questionRight = MIN(56, MAX(24, NSWidth(screenFrame) * .037));
    CGFloat questionBottom = 52 + questionWidth * 169 / 226;
    CGFloat buttonRight = questionRight + questionWidth * 14 / 226;
    NSRect frame = NSMakeRect(round(NSMaxX(screenFrame) - buttonRight - DesktopControlWidth),
                              round(NSMaxY(screenFrame) - questionBottom - 6 - DesktopControlHeight),
                              DesktopControlWidth, DesktopControlHeight);
    NSPanel *panel = self.desktopControls[display];
    if (panel) {
        [panel setFrame:frame display:YES];
        return;
    }

    panel = [[NSPanel alloc] initWithContentRect:frame
                                      styleMask:NSWindowStyleMaskBorderless | NSWindowStyleMaskNonactivatingPanel
                                        backing:NSBackingStoreBuffered defer:NO];
    panel.title = @"鹅卵石桌面控制";
    // Keep the button above Finder's desktop and below regular application windows.
    panel.level = CGWindowLevelForKey(kCGDesktopIconWindowLevelKey) + 1;
    panel.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces |
                               NSWindowCollectionBehaviorStationary |
                               NSWindowCollectionBehaviorIgnoresCycle;
    panel.opaque = NO;
    panel.backgroundColor = NSColor.clearColor;
    panel.hasShadow = NO;
    panel.hidesOnDeactivate = NO;

    PebbleDesktopButton *button = [[PebbleDesktopButton alloc] initWithFrame:
        NSMakeRect(0, 0, DesktopControlWidth, DesktopControlHeight)];
    NSURL *labelURL = [NSBundle.mainBundle URLForResource:@"refresh-label" withExtension:@"png"];
    NSImage *label = [[NSImage alloc] initWithContentsOfURL:labelURL];
    label.size = NSMakeSize(DesktopControlWidth, DesktopControlHeight);
    label.template = YES;
    button.bordered = NO;
    button.image = label;
    button.contentTintColor = NSColor.clearColor;
    button.imageScaling = NSImageScaleNone;
    button.imagePosition = NSImageOnly;
    button.toolTip = @"重新抛一颗鹅卵石";
    button.accessibilityLabel = @"重新抛";
    button.target = self;
    button.action = @selector(rethrowDesktopButton:);
    panel.contentView = button;
    self.desktopControls[display] = panel;
    [panel orderFrontRegardless];
}

- (void)userContentController:(WKUserContentController *)controller
      didReceiveScriptMessage:(WKScriptMessage *)message {
    if ([message.name isEqualToString:@"pebbleHistory"]) {
        NSWindow *window = message.webView.window;
        NSNumber *display = window.screen.deviceDescription[@"NSScreenNumber"];
        if (!self.testPreviewPath && message.frameInfo.mainFrame && display &&
            self.desktopWindows[display] == window && [message.body isKindOfClass:NSDictionary.class]) {
            NSMutableDictionary *history = [NSMutableDictionary dictionary];
            for (NSString *key in @[@"current", @"previous"]) {
                NSDictionary *stone = message.body[key];
                if ([stone isKindOfClass:NSDictionary.class]) history[key] = stone;
            }
            self.pebbleHistory[display.stringValue] = history;
            [NSUserDefaults.standardUserDefaults setObject:self.pebbleHistory forKey:PebbleHistoryKey];
        }
        return;
    }
    if (![message.name isEqualToString:PebbleToneMessage] ||
        ![message.body isKindOfClass:NSNumber.class]) return;
    NSWindow *wallpaper = message.webView.window;
    NSNumber *display = wallpaper.screen.deviceDescription[@"NSScreenNumber"];
    if (!display || self.desktopWindows[display] != wallpaper) return;
    NSUInteger tone = [message.body unsignedIntegerValue];
    if (tone > 0xFFFFFF) return;
    NSButton *button = (NSButton *)self.desktopControls[display].contentView;
    button.contentTintColor = [NSColor colorWithSRGBRed:((tone >> 16) & 255) / 255.0
                                               green:((tone >> 8) & 255) / 255.0
                                                blue:(tone & 255) / 255.0 alpha:1];
}

// The system menu bar samples the native wallpaper underneath our desktop window.
- (void)syncNativeDesktopBackground:(BOOL)restore {
    if (self.testPreviewPath || self.shotPath) return;

    NSString *staticPath = [NSUserDefaults.standardUserDefaults stringForKey:StaticWallpaperPathKey];
    if (staticPath && [NSFileManager.defaultManager fileExistsAtPath:staticPath]) return;

    NSString *preset = self.backgroundPreset;
    NSURL *background = nil;
    if (!restore && ([preset isEqualToString:@"nord0"] || [preset isEqualToString:@"nord3"])) {
        background = [NSBundle.mainBundle URLForResource:[@"desktop-base-" stringByAppendingString:preset]
                                           withExtension:@"png"];
    }

    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSMutableDictionary *originals = [[defaults dictionaryForKey:OriginalDesktopImagesKey] mutableCopy]
        ?: [NSMutableDictionary dictionary];
    NSWorkspace *workspace = NSWorkspace.sharedWorkspace;
    for (NSScreen *screen in NSScreen.screens) {
        NSNumber *display = screen.deviceDescription[@"NSScreenNumber"];
        if (!display) continue;
        NSString *key = display.stringValue;
        NSURL *current = [workspace desktopImageURLForScreen:screen];
        NSString *filename = current.lastPathComponent;
        BOOL managed = [filename isEqualToString:@"desktop-base-nord0.png"] ||
                       [filename isEqualToString:@"desktop-base-nord3.png"];
        if (background) {
            if ([current.path isEqualToString:background.path] || !current) continue;
            if (!managed) {
                NSDictionary *options = [workspace desktopImageOptionsForScreen:screen] ?: @{};
                NSData *encodedOptions = [NSKeyedArchiver archivedDataWithRootObject:options
                                                              requiringSecureCoding:YES error:nil];
                originals[key] = @{@"url":current.absoluteString, @"options":encodedOptions ?: NSData.data};
                [defaults setObject:originals forKey:OriginalDesktopImagesKey];
            }
            NSError *error = nil;
            if (![workspace setDesktopImageURL:background forScreen:screen options:@{} error:&error]) {
                NSLog(@"Could not synchronize wallpaper for display %@: %@", key, error.localizedDescription);
            }
        } else if (originals[key]) {
            if (managed) {
                NSDictionary *original = originals[key];
                NSURL *url = [NSURL URLWithString:original[@"url"]];
                NSSet *classes = [NSSet setWithArray:@[NSDictionary.class, NSString.class, NSNumber.class, NSColor.class]];
                NSDictionary *options = [NSKeyedUnarchiver unarchivedObjectOfClasses:classes
                                                                           fromData:original[@"options"] error:nil] ?: @{};
                if (!url || ![workspace setDesktopImageURL:url forScreen:screen options:options error:nil]) continue;
            }
            [originals removeObjectForKey:key];
        }
    }
    [defaults setObject:originals forKey:OriginalDesktopImagesKey];
}

- (void)applicationWillTerminate:(NSNotification *)notification {
    [self syncNativeDesktopBackground:YES];
}

- (void)refreshDisplays:(NSNotification *)notification {
    [self syncNativeDesktopBackground:NO];
    NSString *staticPath = [NSUserDefaults.standardUserDefaults stringForKey:StaticWallpaperPathKey];
    BOOL staticMode = !self.testPreviewPath && staticPath &&
                      [NSFileManager.defaultManager fileExistsAtPath:staticPath];
    NSMutableSet<NSNumber *> *connected = [NSMutableSet set];
    for (NSScreen *screen in NSScreen.screens) {
        NSNumber *display = screen.deviceDescription[@"NSScreenNumber"];
        if (!display) continue;
        [connected addObject:display];
        NSWindow *window = self.desktopWindows[display];
        if (window) {
            [window setFrame:screen.frame display:YES];
            [self placeDesktopControlOnScreen:screen display:display];
            NSPanel *panel = self.desktopControls[display];
            if (staticMode) {
                [window orderOut:nil];
                [panel orderOut:nil];
            } else {
                if (!window.isVisible) [window orderFrontRegardless];
                if (!panel.isVisible) [panel orderFrontRegardless];
            }
            continue;
        }
        window = [[NSWindow alloc] initWithContentRect:screen.frame
                                           styleMask:NSWindowStyleMaskBorderless
                                             backing:NSBackingStoreBuffered defer:NO];
        window.level = CGWindowLevelForKey(kCGDesktopWindowLevelKey) + 1;
        window.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces |
                                    NSWindowCollectionBehaviorStationary |
                                    NSWindowCollectionBehaviorIgnoresCycle;
        window.backgroundColor = [NSColor colorWithSRGBRed:238.0/255 green:238.0/255 blue:231.0/255 alpha:1];
        window.ignoresMouseEvents = YES;
        window.hasShadow = NO;
        window.hidesOnDeactivate = NO;
        NSString *config = self.rendererConfigScript;
        if (!self.testPreviewPath) {
            NSDictionary *history = self.pebbleHistory[display.stringValue] ?: @{};
            config = [config stringByAppendingFormat:@"window.pebbleHistory = %@;%@",
                      [self jsonForPebble:history], self.smartPauseScript];
        }
        window.contentView = [self newRendererWithConfig:config desktop:YES];
        self.desktopWindows[display] = window;
        if (!staticMode) [window orderFrontRegardless];
        [self placeDesktopControlOnScreen:screen display:display];
        if (staticMode) [self.desktopControls[display] orderOut:nil];
    }
    for (NSNumber *display in self.desktopWindows.allKeys) {
        if ([connected containsObject:display]) continue;
        [self.desktopWindows[display] orderOut:nil];
        [self.desktopWindows removeObjectForKey:display];
        [self.desktopControls[display] orderOut:nil];
        [self.desktopControls removeObjectForKey:display];
    }
    [self rebuildRethrowMenu];
}

#pragma mark - Settings window

- (void)showSettings:(id)sender {
    if (!self.settings) [self buildSettings];
    [NSApp activateIgnoringOtherApps:YES];
    [self.settings makeKeyAndOrderFront:nil];
}

- (void)buildSettings {
    NSWindow *window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0, 0, 840, 580)
        styleMask:NSWindowStyleMaskTitled | NSWindowStyleMaskClosable | NSWindowStyleMaskResizable |
                  NSWindowStyleMaskFullSizeContentView
          backing:NSBackingStoreBuffered defer:NO];
    window.title = @"鹅卵石设置";
#if __has_include(<Sparkle/Sparkle.h>)
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(settingsDidClose:)
        name:NSWindowWillCloseNotification object:window];
#endif
    window.titlebarAppearsTransparent = YES;
    window.releasedWhenClosed = NO;
    window.minSize = NSMakeSize(760, 520);

    window.opaque = NO;
    window.backgroundColor = NSColor.clearColor;

    NSVisualEffectView *glass = [NSVisualEffectView new];
    glass.material = NSVisualEffectMaterialUnderWindowBackground;
    glass.blendingMode = NSVisualEffectBlendingModeBehindWindow;
    glass.state = NSVisualEffectStateActive;
    glass.alphaValue = .35;

    NSView *sidebar = [NSView new];
    sidebar.translatesAutoresizingMaskIntoConstraints = NO;

    self.sectionButtons = [NSMutableArray array];
    NSArray *sections = @[@[@"通用", @"settings"], @[@"收藏", @"heart"], @[@"石头证", @"id-badge"], @[@"关于", @"info"]];
    NSStackView *list = [NSStackView stackViewWithViews:@[]];
    list.orientation = NSUserInterfaceLayoutOrientationVertical;
    list.alignment = NSLayoutAttributeLeading;
    list.spacing = 5;
    list.edgeInsets = NSEdgeInsetsMake(12, 10, 12, 10);
    list.translatesAutoresizingMaskIntoConstraints = NO;
    [sections enumerateObjectsUsingBlock:^(NSArray *section, NSUInteger index, BOOL *stop) {
        NSButton *row = [NSButton buttonWithTitle:section[0] target:self
                                           action:@selector(selectSection:)];
        row.image = [self settingsIcon:section[1]];
        row.imagePosition = NSImageLeft;
        row.bordered = NO;
        row.alignment = NSTextAlignmentLeft;
        row.font = [NSFont systemFontOfSize:13];
        row.tag = (NSInteger)index;
        row.translatesAutoresizingMaskIntoConstraints = NO;
        // A box behind the button gives the rounded selection without the heavy
        // slab a recessed bezel paints, and follows light and dark on its own.
        PebbleRoundedView *seat = [self roundedViewFilled:NSColor.clearColor radius:6];
        [self pin:row into:seat inset:4];
        [list addArrangedSubview:seat];
        [seat.widthAnchor constraintEqualToAnchor:list.widthAnchor constant:-20].active = YES;
        [self.sectionButtons addObject:row];
    }];
    [sidebar addSubview:list];

    self.panes = @[[self generalPane], [NSView new], [self passPane], [self aboutPane]];
    NSView *body = [NSView new];
    body.translatesAutoresizingMaskIntoConstraints = NO;
    self.settingsBody = body;

    NSView *root = window.contentView;
    [self pin:glass into:root inset:0];
    [root addSubview:sidebar];
    [root addSubview:body];
    NSLayoutGuide *content = window.contentLayoutGuide;
    [NSLayoutConstraint activateConstraints:@[
        [sidebar.topAnchor constraintEqualToAnchor:content.topAnchor],
        [sidebar.bottomAnchor constraintEqualToAnchor:root.bottomAnchor],
        [sidebar.leadingAnchor constraintEqualToAnchor:root.leadingAnchor],
        [sidebar.widthAnchor constraintEqualToConstant:196],
        [list.topAnchor constraintEqualToAnchor:sidebar.topAnchor],
        [list.leadingAnchor constraintEqualToAnchor:sidebar.leadingAnchor],
        [list.trailingAnchor constraintEqualToAnchor:sidebar.trailingAnchor],
        [body.topAnchor constraintEqualToAnchor:content.topAnchor],
        [body.bottomAnchor constraintEqualToAnchor:root.bottomAnchor],
        [body.leadingAnchor constraintEqualToAnchor:sidebar.trailingAnchor],
        [body.trailingAnchor constraintEqualToAnchor:root.trailingAnchor],
    ]];

    // Remembers where the user left it, which a settings window is expected to do.
    [window setFrameAutosaveName:@"PebbleSettingsWindow"];
    if (NSIsEmptyRect(window.frame) || !window.frameAutosaveName.length) [window center];
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(settingsWillClose:)
                 name:NSWindowWillCloseNotification object:window];
    self.settings = window;
    [self showPaneAtIndex:0];
}

- (void)selectSection:(NSButton *)sender {
    [self showPaneAtIndex:sender.tag];
}

- (void)showPaneAtIndex:(NSInteger)index {
    self.selectedSettingsPane = index;
    for (NSButton *button in self.sectionButtons) {
        PebbleRoundedView *seat = (PebbleRoundedView *)button.superview;
        if ([seat isKindOfClass:PebbleRoundedView.class]) {
            seat.fill = button.tag == index ?
                NSColor.unemphasizedSelectedContentBackgroundColor : NSColor.clearColor;
        }
    }
    // Keep the panes alive so the pass card keeps its stone across tab changes.
    for (NSView *view in self.settingsBody.subviews.copy) [view removeFromSuperview];
    NSView *pane = index == FavoritesPaneIndex ? [self favoritesPane] : self.panes[index];
    pane.translatesAutoresizingMaskIntoConstraints = NO;
    [self.settingsBody addSubview:pane];
    [NSLayoutConstraint activateConstraints:@[
        [pane.topAnchor constraintEqualToAnchor:self.settingsBody.topAnchor],
        [pane.bottomAnchor constraintEqualToAnchor:self.settingsBody.bottomAnchor],
        [pane.leadingAnchor constraintEqualToAnchor:self.settingsBody.leadingAnchor],
        [pane.trailingAnchor constraintEqualToAnchor:self.settingsBody.trailingAnchor],
    ]];
}

- (NSView *)stageAround:(NSView *)view height:(CGFloat)height {
    [view.heightAnchor constraintEqualToConstant:height].active = YES;
    // The wallpaper's own paper colour, so the stone sits on its usual ground.
    PebbleRoundedView *stage = [self roundedViewFilled:
        [NSColor colorWithSRGBRed:238.0/255 green:238.0/255 blue:231.0/255 alpha:1] radius:10];
    [self pin:view into:stage inset:0];
    return stage;
}

- (void)selectBackground:(NSButton *)sender {
    NSUInteger index = (NSUInteger)sender.tag;
    if (index >= BackgroundCount) return;
    self.backgroundPreset = @(BackgroundKeys[index]);
    [self syncNativeDesktopBackground:NO];
    if (!self.testPreviewPath) {
        [NSUserDefaults.standardUserDefaults setObject:self.backgroundPreset forKey:BackgroundPreference];
    }
    for (NSButton *button in self.backgroundButtons) {
        button.state = button == sender ? NSControlStateValueOn : NSControlStateValueOff;
        NSString *label = BackgroundLabels[button.tag];
        button.title = button == sender ? [label stringByAppendingString:@" ✓"] : label;
    }
    NSString *script = [self.backgroundConfigScript stringByAppendingString:@"window.pebbleRedraw?.();"];
    [self forEachRenderer:^(WKWebView *web) {
        [web evaluateJavaScript:script completionHandler:nil];
    }];
}

- (NSView *)backgroundPicker {
    self.backgroundButtons = [NSMutableArray array];
    NSStackView *choices = [NSStackView stackViewWithViews:@[]];
    choices.distribution = NSStackViewDistributionFillEqually;
    choices.spacing = 8;
    for (NSUInteger index = 0; index < BackgroundCount; index++) {
        NSString *key = @(BackgroundKeys[index]);
        NSUInteger rgb = BackgroundColors[index];
        NSColor *color = [NSColor colorWithSRGBRed:((rgb >> 16) & 255) / 255.0
                                            green:((rgb >> 8) & 255) / 255.0
                                             blue:(rgb & 255) / 255.0 alpha:1];
        NSImage *thumbnail = [NSImage imageWithSize:NSMakeSize(96, 43) flipped:NO drawingHandler:^BOOL(NSRect rect) {
            [color setFill];
            [[NSBezierPath bezierPathWithRoundedRect:rect xRadius:5 yRadius:5] fill];
            return YES;
        }];
        NSButton *choice = [NSButton buttonWithTitle:BackgroundLabels[index] image:thumbnail
                                            target:self action:@selector(selectBackground:)];
        [choice setButtonType:NSButtonTypePushOnPushOff];
        choice.bezelStyle = NSBezelStyleRegularSquare;
        choice.imagePosition = NSImageAbove;
        choice.imageScaling = NSImageScaleNone;
        choice.tag = index;
        choice.state = [key isEqualToString:self.backgroundPreset] ? NSControlStateValueOn : NSControlStateValueOff;
        if (choice.state == NSControlStateValueOn) choice.title = [choice.title stringByAppendingString:@" ✓"];
        [choice.heightAnchor constraintEqualToConstant:68].active = YES;
        [choices addArrangedSubview:choice];
        [self.backgroundButtons addObject:choice];
    }
    return [self settingsGroup:@"桌面背景" containing:choices];
}

- (NSView *)settingsGroup:(NSString *)name containing:(NSView *)choices {
    NSTextField *title = [NSTextField labelWithString:name];
    title.font = [NSFont systemFontOfSize:14 weight:NSFontWeightSemibold];
    NSStackView *group = [NSStackView stackViewWithViews:@[title, choices]];
    group.orientation = NSUserInterfaceLayoutOrientationVertical;
    group.alignment = NSLayoutAttributeLeading;
    group.spacing = 8;
    [choices.widthAnchor constraintEqualToAnchor:group.widthAnchor].active = YES;
    return group;
}

- (NSView *)generalPane {
    self.texturePopUp = [self popUpWithKeys:PebbleTextureKeys labels:PebbleTextureLabels
        count:PebbleTextureCount selected:self.texture action:@selector(selectTexture:)];
    self.palettePopUp = [self popUpWithKeys:PebbleColorKeys labels:PebbleColorLabels
        count:PebbleColorCount selected:self.palette action:@selector(selectPalette:)];
    self.facePopUp = [self popUpWithKeys:PebbleFaceKeys labels:PebbleFaceLabels
        count:PebbleFaceCount selected:self.face action:@selector(selectFace:)];
    self.rotationSwitch = [self switchOn:!self.paused action:@selector(togglePause:)];

    NSView *stone = [self cardWithRows:@[
        [self rowWithSymbol:@"repeat" title:@"换一颗鹅卵石"
                   subtitle:nil
                    control:[self actionButton:@"换一颗" action:@selector(changePebble:)]],
        [self rowWithSymbol:@"grid" title:@"材质"
                   subtitle:nil control:self.texturePopUp],
        [self rowWithSymbol:@"palette" title:@"颜色"
                   subtitle:nil control:self.palettePopUp],
        [self rowWithSymbol:@"smile" title:@"脸孔"
                   subtitle:nil
                    control:self.facePopUp],
    ]];
    self.tiltSlider = [NSSlider sliderWithValue:self.tiltDegrees minValue:-TiltLimit maxValue:TiltLimit
                                         target:self action:@selector(selectTilt:)];
    self.tiltSlider.continuous = YES;
    self.tiltSlider.accessibilityLabel = @"倾斜角度";
    [self.tiltSlider.widthAnchor constraintEqualToConstant:120].active = YES;
    self.tiltValue = [NSTextField labelWithString:[self tiltTitle:self.tiltDegrees]];
    self.tiltValue.font = [NSFont monospacedDigitSystemFontOfSize:12 weight:NSFontWeightRegular];
    self.tiltValue.alignment = NSTextAlignmentRight;
    [self.tiltValue.widthAnchor constraintEqualToConstant:42].active = YES;
    NSStackView *tiltControl = [NSStackView stackViewWithViews:@[self.tiltSlider, self.tiltValue]];
    tiltControl.spacing = 8;
    self.speedPicker = [[NSPopUpButton alloc] initWithFrame:NSZeroRect pullsDown:NO];
    self.speedPicker.target = self;
    self.speedPicker.action = @selector(selectRotationRate:);
    self.speedPicker.accessibilityLabel = @"旋转速度";
    for (NSMenuItem *item in self.speedMenu.itemArray) {
        [self.speedPicker addItemWithTitle:item.title];
        self.speedPicker.lastItem.representedObject = item.representedObject;
    }
    [self syncMotionControls];
    NSView *motion = [self cardWithRows:@[
        [self rowWithSymbol:@"compass-drawing" title:@"倾斜角度"
                   subtitle:@"0° 使用原始角度" control:tiltControl],
        [self rowWithSymbol:@"gauge" title:@"旋转速度" subtitle:nil control:self.speedPicker],
        [self rowWithSymbol:@"rotate-cw" title:@"旋转"
                   subtitle:nil control:self.rotationSwitch],
    ]];
    return [self paneWithCards:@[[self backgroundPicker],
        [self settingsGroup:@"鹅卵石" containing:stone],
        [self settingsGroup:@"旋转与倾斜" containing:motion]]];
}

// The number is the seed, so the card is literally generated from its own
// serial. Issued once and kept, or it would stop being an identity.
- (NSInteger)passNumber {
    if (self.shotPath && self.shotPassNumber > 0) return self.shotPassNumber;
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSNumber *issued = [defaults objectForKey:PassPreference];
    if ([issued isKindOfClass:NSNumber.class] && issued.integerValue < PassLegacyFloor) {
        return issued.integerValue;
    }
    // The slot the install falls into is the number, so installs are ordered
    // and separated without a server handing anything out.
    double elapsed = NSDate.date.timeIntervalSince1970 - PassEpoch;
    NSInteger number = PassFirstOpenNumber +
        (NSInteger)fmax(0., floor(elapsed / PassSlotSeconds));
    [defaults setInteger:number forKey:PassPreference];
    return number;
}

// No.02 is handed out rather than drawn, so its stone is picked instead of
// left to the number: a rounded block-family shape in the green hue band.
// Chosen by rendering candidates, because the silhouette comes from a
// per-view contour that the stone's ratio does not predict.
static const NSInteger PassAuthorSeed = 13612;

- (NSInteger)passStoneSeed {
    return self.passNumber == 2 ? PassAuthorSeed : self.passNumber;
}

- (NSInteger)passPaletteSeed {
    return self.passNumber == 2 ? PassAuthorSeed : self.passNumber;
}

- (NSString *)passConfigScript {
    // Both seeds are pinned and the user's choices deliberately left out, so the
    // card is the same stone in the same colour every time it is opened.
    return [NSString stringWithFormat:@"window.pebbleConfig = {seed: %ld, paletteSeed: %ld,"
            " texture: null, palette: null, faces: null, staticPass: true, number: %ld};",
            (long)self.passStoneSeed, (long)self.passPaletteSeed, (long)self.passNumber];
}

- (NSView *)passPane {
    self.passRenderer = [self newRendererWithConfig:self.passConfigScript desktop:NO];
    NSView *card = [self stageAround:self.passRenderer height:440];

    NSView *actions = [self cardWithRows:@[
        [self rowWithSymbol:@"copy" title:@"复制编号"
                   subtitle:@"把 No. 编号复制到剪贴板"
                    control:[self actionButton:@"复制" action:@selector(copyPassNumber:)]],
    ]];
    return [self paneWithCards:@[card, actions]];
}

- (void)capturePassForVerification {
    NSString *script = @"const r=document.getElementById('root'), stone=document.getElementById('pass-stone');"
        "await stone.decode(); const frame=stone.src;"
        "r.querySelector('button').click();"
        "await new Promise(resolve=>setTimeout(resolve, 600));"
        "return {still:r.inert && stone.naturalWidth>0 && frame===stone.src,"
        "number:document.getElementById('pass-number').textContent,"
        "tone:document.documentElement.style.getPropertyValue('--pass-tone')};";
    [self.passRenderer callAsyncJavaScript:script arguments:@{} inFrame:nil
        inContentWorld:WKContentWorld.pageWorld completionHandler:^(NSDictionary *result, NSError *error) {
        NSString *expected = [NSString stringWithFormat:@"%02ld", (long)self.passNumber];
        if (error || ![result[@"still"] boolValue] || ![result[@"number"] isEqual:expected] ||
            ![result[@"tone"] length]) {
            NSLog(@"Stone pass verification failed: %@ %@", result, error);
            exit(5);
        }
        NSLog(@"Verified stone pass %@, glow RGB %@", expected, result[@"tone"]);
        [self.passRenderer takeSnapshotWithConfiguration:nil completionHandler:^(NSImage *image, NSError *snapshotError) {
            NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:image.TIFFRepresentation];
            NSData *png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
            if (snapshotError || ![png writeToFile:self.shotPath atomically:YES]) exit(6);
            [NSApp terminate:nil];
        }];
    }];
}

- (void)copyPassNumber:(id)sender {
    NSPasteboard *board = NSPasteboard.generalPasteboard;
    [board clearContents];
    [board setString:[NSString stringWithFormat:@"No. %02ld", (long)self.passNumber]
             forType:NSPasteboardTypeString];
}

- (NSView *)aboutPane {
