// Both the menu and the settings window drive the same state, so whichever one
// the change came from, the other has to catch up.
- (void)syncSettingsControls {
    [self selectChoice:self.texture inPopUp:self.texturePopUp];
    [self selectChoice:self.palette inPopUp:self.palettePopUp];
    [self selectChoice:self.face inPopUp:self.facePopUp];
    self.rotationSwitch.state = self.paused ? NSControlStateValueOff : NSControlStateValueOn;
}

- (void)settingsWillClose:(NSNotification *)notification {
#if __has_include(<Sparkle/Sparkle.h>)
    // The window still reports itself visible during this notification.
    dispatch_async(dispatch_get_main_queue(), ^{ [self installPendingUpdateIfIdle]; });
#endif
}

#pragma mark - Settings building blocks

- (NSImage *)settingsIcon:(NSString *)name {
    NSURL *url = [NSBundle.mainBundle URLForResource:name withExtension:@"png" subdirectory:@"kubai-settings"];
    NSImage *icon = [[NSImage alloc] initWithContentsOfURL:url];
    icon.size = NSMakeSize(24, 24);
    return icon;
}

- (PebbleRoundedView *)roundedViewFilled:(NSColor *)fill radius:(CGFloat)radius {
    PebbleRoundedView *view = [PebbleRoundedView new];
    view.fill = fill;
    view.radius = radius;
    view.translatesAutoresizingMaskIntoConstraints = NO;
    return view;
}

- (void)pin:(NSView *)view into:(NSView *)container inset:(CGFloat)inset {
    view.translatesAutoresizingMaskIntoConstraints = NO;
    [container addSubview:view];
    [NSLayoutConstraint activateConstraints:@[
        [view.topAnchor constraintEqualToAnchor:container.topAnchor constant:inset],
        [view.bottomAnchor constraintEqualToAnchor:container.bottomAnchor constant:-inset],
        [view.leadingAnchor constraintEqualToAnchor:container.leadingAnchor constant:inset],
        [view.trailingAnchor constraintEqualToAnchor:container.trailingAnchor constant:-inset],
    ]];
}

- (NSTextField *)caption:(NSString *)text {
    // Single line on purpose: a wrapping label reports a runaway intrinsic width
    // unless its preferredMaxLayoutWidth is maintained, which wrecks the rows.
    NSTextField *label = [NSTextField labelWithString:text];
    label.lineBreakMode = NSLineBreakByTruncatingTail;
    label.font = [NSFont systemFontOfSize:11];
    label.textColor = NSColor.secondaryLabelColor;
    label.selectable = NO;
    return label;
}

- (NSView *)rowWithSymbol:(NSString *)symbol title:(NSString *)title
                 subtitle:(NSString *)subtitle control:(NSView *)control {
    NSTextField *heading = [NSTextField labelWithString:title];
    heading.font = [NSFont systemFontOfSize:13];
    NSStackView *text = [NSStackView stackViewWithViews:@[heading]];
    text.orientation = NSUserInterfaceLayoutOrientationVertical;
    text.alignment = NSLayoutAttributeLeading;
    text.spacing = 2;
    if (subtitle.length) {
        NSTextField *detail = [self caption:subtitle];
        [text addArrangedSubview:detail];
        [detail setContentCompressionResistancePriority:NSLayoutPriorityDefaultLow
                                         forOrientation:NSLayoutConstraintOrientationHorizontal];
    }
    [text setContentHuggingPriority:NSLayoutPriorityDefaultLow
                     forOrientation:NSLayoutConstraintOrientationHorizontal];

    NSMutableArray *pieces = [NSMutableArray array];
    if (symbol.length) {
        NSImageView *icon = [NSImageView imageViewWithImage:
            [self settingsIcon:symbol]];
        icon.accessibilityElement = NO;
        [icon.widthAnchor constraintEqualToConstant:24].active = YES;
        [icon.heightAnchor constraintEqualToConstant:24].active = YES;
        [pieces addObject:icon];
    }
    [pieces addObject:text];
    if (control) {
        // A flexible spacer is the dependable way to push the control to the
        // trailing edge; hugging priorities alone leave it next to the subtitle.
        NSView *spacer = [NSView new];
        [spacer setContentHuggingPriority:NSLayoutPriorityDefaultLow - 1
                           forOrientation:NSLayoutConstraintOrientationHorizontal];
        [spacer setContentCompressionResistancePriority:NSLayoutPriorityDefaultLow - 1
                                         forOrientation:NSLayoutConstraintOrientationHorizontal];
        [pieces addObject:spacer];
        [pieces addObject:control];
    }

    NSStackView *row = [NSStackView stackViewWithViews:pieces];
    row.orientation = NSUserInterfaceLayoutOrientationHorizontal;
    row.alignment = NSLayoutAttributeCenterY;
    row.spacing = 10;
    row.edgeInsets = NSEdgeInsetsMake(7, 14, 7, 14);
    return row;
}

- (NSView *)cardWithRows:(NSArray<NSView *> *)rows {
    NSStackView *stack = [NSStackView stackViewWithViews:@[]];
    stack.orientation = NSUserInterfaceLayoutOrientationVertical;
    stack.alignment = NSLayoutAttributeLeading;
    stack.spacing = 0;
    for (NSView *row in rows) {
        if (stack.arrangedSubviews.count) {
            NSBox *line = [NSBox new];
            line.boxType = NSBoxSeparator;
            [stack addArrangedSubview:line];
            [line.widthAnchor constraintEqualToAnchor:stack.widthAnchor].active = YES;
        }
        [stack addArrangedSubview:row];
        [row.widthAnchor constraintEqualToAnchor:stack.widthAnchor].active = YES;
    }
    // Semantic colour so the card follows light and dark on its own.
    NSColor *cardColor = [NSColor colorWithName:nil dynamicProvider:^NSColor *(NSAppearance *appearance) {
        BOOL dark = [[appearance bestMatchFromAppearancesWithNames:@[NSAppearanceNameAqua, NSAppearanceNameDarkAqua]]
                     isEqualToString:NSAppearanceNameDarkAqua];
        return [NSColor colorWithSRGBRed:dark ? .17 : .89
                                   green:dark ? .17 : .89
                                    blue:dark ? .17 : .89 alpha:.55];
    }];
    PebbleRoundedView *card = [self roundedViewFilled:cardColor radius:10];
    card.stroke = NSColor.separatorColor;
    [self pin:stack into:card inset:0];
    return card;
}

- (NSScrollView *)paneWithCards:(NSArray<NSView *> *)cards {
    NSStackView *column = [NSStackView stackViewWithViews:cards];
    column.orientation = NSUserInterfaceLayoutOrientationVertical;
    column.alignment = NSLayoutAttributeLeading;
    column.spacing = 14;
    column.edgeInsets = NSEdgeInsetsMake(22, 22, 22, 22);
    column.translatesAutoresizingMaskIntoConstraints = NO;

    NSScrollView *scroll = [NSScrollView new];
    scroll.drawsBackground = NO;
    scroll.hasVerticalScroller = YES;
    scroll.translatesAutoresizingMaskIntoConstraints = NO;
    PebbleFlippedView *document = [PebbleFlippedView new];
    document.translatesAutoresizingMaskIntoConstraints = NO;
    [document addSubview:column];
    scroll.documentView = document;
    [NSLayoutConstraint activateConstraints:@[
        [document.widthAnchor constraintEqualToAnchor:scroll.contentView.widthAnchor],
        [document.topAnchor constraintEqualToAnchor:scroll.contentView.topAnchor],
        [column.topAnchor constraintEqualToAnchor:document.topAnchor],
        [column.leadingAnchor constraintEqualToAnchor:document.leadingAnchor],
        [column.trailingAnchor constraintEqualToAnchor:document.trailingAnchor],
        [column.bottomAnchor constraintEqualToAnchor:document.bottomAnchor],
    ]];
    for (NSView *card in cards) {
        [card.widthAnchor constraintEqualToAnchor:column.widthAnchor
                                         constant:-(column.edgeInsets.left +
                                                    column.edgeInsets.right)].active = YES;
    }
    return scroll;
}

- (NSPopUpButton *)popUpWithKeys:(const char *const *)keys labels:(const char *const *)labels
                           count:(NSUInteger)count selected:(NSString *)selected
                          action:(SEL)action {
    NSPopUpButton *popUp = [[NSPopUpButton alloc] initWithFrame:NSZeroRect pullsDown:NO];
    popUp.target = self;
    popUp.action = action;
    [popUp addItemWithTitle:@"随机"];
    popUp.lastItem.representedObject = @"";
    for (NSUInteger index = 0; index < count; index++) {
        [popUp addItemWithTitle:@(labels[index])];
        popUp.lastItem.representedObject = @(keys[index]);
    }
    [popUp.widthAnchor constraintGreaterThanOrEqualToConstant:150].active = YES;
    [popUp setContentHuggingPriority:NSLayoutPriorityRequired
                      forOrientation:NSLayoutConstraintOrientationHorizontal];
    [self selectChoice:selected inPopUp:popUp];
    return popUp;
}

- (void)selectChoice:(NSString *)choice inPopUp:(NSPopUpButton *)popUp {
    for (NSMenuItem *item in popUp.itemArray) {
        if ([item.representedObject isEqualToString:choice ?: @""]) [popUp selectItem:item];
    }
}

- (NSButton *)actionButton:(NSString *)title action:(SEL)action {
    NSButton *button = [NSButton buttonWithTitle:title target:self action:action];
    button.bezelStyle = NSBezelStyleRounded;
    [button setContentHuggingPriority:NSLayoutPriorityRequired
                       forOrientation:NSLayoutConstraintOrientationHorizontal];
    return button;
}

- (NSSwitch *)switchOn:(BOOL)on action:(SEL)action {
    NSSwitch *toggle = [NSSwitch new];
    toggle.state = on ? NSControlStateValueOn : NSControlStateValueOff;
    toggle.target = self;
    toggle.action = action;
    [toggle setContentHuggingPriority:NSLayoutPriorityRequired
                       forOrientation:NSLayoutConstraintOrientationHorizontal];
    return toggle;
}

- (NSString *)jsonForPebble:(NSDictionary *)object {
    NSData *data = [NSJSONSerialization dataWithJSONObject:object options:0 error:nil];
    return [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding] ?: @"null";
}

- (NSData *)wallpaperPNGFromBase64:(id)value size:(WallpaperExportSize)size {
    if (![value isKindOfClass:NSString.class]) return nil;
    NSData *png = [[NSData alloc] initWithBase64EncodedString:value options:0];
    NSBitmapImageRep *image = png ? [NSBitmapImageRep imageRepWithData:png] : nil;
    return image.pixelsWide == size.width && image.pixelsHigh == size.height ? png : nil;
}

- (void)showWallpaperError:(NSString *)detail {
    [NSApp activateIgnoringOtherApps:YES];
    NSAlert *alert = [NSAlert new];
    alert.messageText = @"无法生成静态壁纸";
    alert.informativeText = detail;
    [alert runModal];
}

- (void)withWallpaperPNGForSize:(WallpaperExportSize)size completion:(void (^)(NSData *))completion {
    NSString *path = [NSUserDefaults.standardUserDefaults stringForKey:StaticWallpaperPathKey];
    NSData *saved = path && size.width == WallpaperSizes[0].width && size.height == WallpaperSizes[0].height
        ? [NSData dataWithContentsOfFile:path] : nil;
    if (saved) {
        completion(saved);
        return;
    }
    NSNumber *display = NSScreen.screens.firstObject.deviceDescription[@"NSScreenNumber"];
    WKWebView *web = display ? (WKWebView *)self.desktopWindows[display].contentView : nil;
    if (!web) {
        [self showWallpaperError:@"当前没有可用的桌面画面。"];
        return;
    }
    NSString *script = [NSString stringWithFormat:@"window.pebbleExport?.(%lu,%lu)",
                        (unsigned long)size.width, (unsigned long)size.height];
    [web evaluateJavaScript:script completionHandler:^(id result, NSError *error) {
        NSData *png = [self wallpaperPNGFromBase64:result size:size];
        if (png) completion(png);
        else [self showWallpaperError:error.localizedDescription ?: @"鹅卵石还在加载，请稍后再试。"];
    }];
}

- (void)exportWallpaper:(NSMenuItem *)sender {
    if ((NSUInteger)sender.tag >= WallpaperSizeCount) return;
    WallpaperExportSize size = WallpaperSizes[sender.tag];
    [self withWallpaperPNGForSize:size completion:^(NSData *png) {
        [NSApp activateIgnoringOtherApps:YES];
        NSSavePanel *panel = [NSSavePanel savePanel];
        panel.allowedContentTypes = @[UTTypePNG];
        panel.nameFieldStringValue = [NSString stringWithFormat:@"鹅卵石壁纸-%@.png", size.name];
        if ([panel runModal] != NSModalResponseOK) return;
        NSError *error = nil;
        if (![png writeToURL:panel.URL options:NSDataWritingAtomic error:&error]) {
            [self showWallpaperError:error.localizedDescription];
        }
    }];
}

- (void)setStaticWallpaper:(id)sender {
    [self withWallpaperPNGForSize:WallpaperSizes[0] completion:^(NSData *png) {
        NSFileManager *files = NSFileManager.defaultManager;
        NSURL *directory = [[files URLsForDirectory:NSApplicationSupportDirectory inDomains:NSUserDomainMask].firstObject
                            URLByAppendingPathComponent:@"Pebble Wallpaper/Static Wallpapers" isDirectory:YES];
        NSURL *url = [directory URLByAppendingPathComponent:[NSUUID.UUID.UUIDString stringByAppendingString:@".png"]];
        NSError *error = nil;
        if (![files createDirectoryAtURL:directory withIntermediateDirectories:YES attributes:nil error:&error] ||
            ![png writeToURL:url options:NSDataWritingAtomic error:&error]) {
            [self showWallpaperError:error.localizedDescription];
            return;
        }

        NSWorkspace *workspace = NSWorkspace.sharedWorkspace;
        NSMutableArray<void (^)(void)> *undo = [NSMutableArray array];
        for (NSScreen *screen in NSScreen.screens) {
            NSURL *previous = [workspace desktopImageURLForScreen:screen];
            NSDictionary *options = [workspace desktopImageOptionsForScreen:screen] ?: @{};
            if (![workspace setDesktopImageURL:url forScreen:screen
                                       options:@{NSWorkspaceDesktopImageScalingKey:@(NSImageScaleProportionallyUpOrDown),
                                                 NSWorkspaceDesktopImageAllowClippingKey:@YES} error:&error]) {
                for (void (^restore)(void) in undo.reverseObjectEnumerator) restore();
                [self showWallpaperError:error.localizedDescription ?: @"macOS 无法设置这张壁纸。"];
                return;
            }
            if (previous) [undo addObject:^{ [workspace setDesktopImageURL:previous forScreen:screen options:options error:nil]; }];
        }
        [NSUserDefaults.standardUserDefaults setObject:url.path forKey:StaticWallpaperPathKey];
        [self refreshDisplays:nil];
    }];
}

- (void)resumeDynamicWallpaper:(id)sender {
    [NSUserDefaults.standardUserDefaults removeObjectForKey:StaticWallpaperPathKey];
    [self refreshDisplays:nil];
}

- (void)previousPebble:(id)sender {
    [self forEachRenderer:^(WKWebView *web) {
        [web evaluateJavaScript:@"window.pebblePrevious?.()" completionHandler:nil];
    }];
}

- (NSView *)favoritesPane {
    NSView *save = [self rowWithSymbol:@"heart" title:@"收藏当前石头"
        subtitle:@"保存主屏幕上的鹅卵石"
        control:[self actionButton:@"收藏" action:@selector(saveFavorite:)]];
    NSMutableArray *rows = [NSMutableArray array];
    [self.favorites enumerateObjectsUsingBlock:^(NSDictionary *stone, NSUInteger index, BOOL *stop) {
        NSButton *restore = [self actionButton:@"设为当前" action:@selector(restoreFavorite:)];
        NSButton *remove = [self actionButton:@"移除" action:@selector(removeFavorite:)];
        restore.tag = remove.tag = index;
        NSStackView *controls = [NSStackView stackViewWithViews:@[restore, remove]];
        NSString *title = [NSString stringWithFormat:@"石头 %lu", (unsigned long)index + 1];
        [rows addObject:[self rowWithSymbol:nil title:title subtitle:[stone[@"colors"] firstObject] control:controls]];
    }];
    NSView *collection = rows.count ? [self cardWithRows:rows] : [self caption:@"还没有收藏的石头"];
    return [self paneWithCards:@[[self cardWithRows:@[save]], collection]];
}

- (void)persistFavorites {
    [NSUserDefaults.standardUserDefaults setObject:self.favorites forKey:PebbleFavoritesKey];
    if (self.settings && self.selectedSettingsPane == FavoritesPaneIndex) {
        [self showPaneAtIndex:FavoritesPaneIndex];
    }
}

- (void)saveFavorite:(id)sender {
    NSNumber *display = NSScreen.screens.firstObject.deviceDescription[@"NSScreenNumber"];
    WKWebView *web = display ? (WKWebView *)self.desktopWindows[display].contentView : nil;
    [web evaluateJavaScript:@"window.pebbleHistory?.current" completionHandler:^(id stone, NSError *error) {
        if ([stone isKindOfClass:NSDictionary.class] && ![self.favorites containsObject:stone]) {
            [self.favorites addObject:stone];
            [self persistFavorites];
        }
    }];
}

- (void)restoreFavorite:(NSButton *)sender {
    if ((NSUInteger)sender.tag >= self.favorites.count) return;
    NSString *script = [NSString stringWithFormat:@"window.pebbleRestore?.(%@)",
                        [self jsonForPebble:self.favorites[sender.tag]]];
    [self forEachRenderer:^(WKWebView *web) {
        [web evaluateJavaScript:script completionHandler:nil];
    }];
}

- (void)removeFavorite:(NSButton *)sender {
    if ((NSUInteger)sender.tag >= self.favorites.count) return;
    [self.favorites removeObjectAtIndex:sender.tag];
    [self persistFavorites];
}

- (NSString *)smartPauseScript {
    BOOL enabled = ![NSUserDefaults.standardUserDefaults boolForKey:SmartPauseDisabledKey];
    BOOL paused = enabled && (self.screenLocked || self.displaysAsleep || self.sessionInactive ||
                             NSProcessInfo.processInfo.lowPowerModeEnabled);
    return [NSString stringWithFormat:@"window.pebbleSmartPaused = %@;", paused ? @"true" : @"false"];
}

- (void)observeSmartPause {
    NSNotificationCenter *workspace = NSWorkspace.sharedWorkspace.notificationCenter;
    for (NSNotificationName name in @[NSWorkspaceScreensDidSleepNotification, NSWorkspaceScreensDidWakeNotification,
                                       NSWorkspaceSessionDidResignActiveNotification, NSWorkspaceSessionDidBecomeActiveNotification]) {
        [workspace addObserver:self selector:@selector(smartPauseChanged:) name:name object:nil];
    }
    NSDistributedNotificationCenter *distributed = NSDistributedNotificationCenter.defaultCenter;
    for (NSNotificationName name in @[@"com.apple.screenIsLocked", @"com.apple.screenIsUnlocked"]) {
        [distributed addObserver:self selector:@selector(smartPauseChanged:) name:name object:nil
              suspensionBehavior:NSNotificationSuspensionBehaviorDeliverImmediately];
    }
    [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(smartPauseChanged:)
        name:NSProcessInfoPowerStateDidChangeNotification object:nil];
}

- (void)smartPauseChanged:(NSNotification *)notification {
    dispatch_async(dispatch_get_main_queue(), ^{
        NSString *name = notification.name;
        if ([name isEqualToString:@"com.apple.screenIsLocked"]) self.screenLocked = YES;
        if ([name isEqualToString:@"com.apple.screenIsUnlocked"]) self.screenLocked = NO;
        if ([name isEqualToString:NSWorkspaceScreensDidSleepNotification]) self.displaysAsleep = YES;
        if ([name isEqualToString:NSWorkspaceScreensDidWakeNotification]) self.displaysAsleep = NO;
        if ([name isEqualToString:NSWorkspaceSessionDidResignActiveNotification]) self.sessionInactive = YES;
        if ([name isEqualToString:NSWorkspaceSessionDidBecomeActiveNotification]) self.sessionInactive = NO;
        [self forEachRenderer:^(WKWebView *web) { [self applyPauseTo:web]; }];
    });
}

- (void)toggleSmartPause:(NSMenuItem *)sender {
    BOOL disabled = sender.state == NSControlStateValueOn;
    [NSUserDefaults.standardUserDefaults setBool:disabled forKey:SmartPauseDisabledKey];
    sender.state = disabled ? NSControlStateValueOff : NSControlStateValueOn;
    [self smartPauseChanged:nil];
}

- (void)forEachRenderer:(void (^)(WKWebView *))action {
    for (NSWindow *window in self.desktopWindows.allValues) action((WKWebView *)window.contentView);
    // The pass stone is deliberately absent: it must never follow these choices.
}

- (void)rebuildRethrowMenu {
    [self.rethrowMenu removeAllItems];
    [self addItem:@"所有屏幕" action:@selector(changePebble:) toMenu:self.rethrowMenu];
    [self.rethrowMenu addItem:NSMenuItem.separatorItem];
    NSArray<NSScreen *> *screens = NSScreen.screens;
    [screens enumerateObjectsUsingBlock:^(NSScreen *screen, NSUInteger index, BOOL *stop) {
        NSNumber *display = screen.deviceDescription[@"NSScreenNumber"];
        if (!display) return;
        NSString *title = index == 0
            ? [NSString stringWithFormat:@"主屏幕 · %@", screen.localizedName]
            : [NSString stringWithFormat:@"屏幕 %lu · %@", (unsigned long)index + 1, screen.localizedName];
        [self addItem:title action:@selector(rethrowMenuScreen:) toMenu:self.rethrowMenu].representedObject = display;
    }];
}

- (void)rethrowDisplay:(NSNumber *)display {
    NSWindow *window = display ? self.desktopWindows[display] : nil;
    if (!window.isVisible) return;
    [(WKWebView *)window.contentView evaluateJavaScript:@"window.pebbleThrow?.()" completionHandler:nil];
}

- (void)rethrowMenuScreen:(NSMenuItem *)sender {
    [self rethrowDisplay:sender.representedObject];
}

- (void)rethrowDesktopButton:(NSButton *)sender {
    [self.desktopControls enumerateKeysAndObjectsUsingBlock:^(NSNumber *display, NSPanel *panel, BOOL *stop) {
        if (panel == sender.window) {
            [self rethrowDisplay:display];
            *stop = YES;
        }
    }];
}

- (void)changePebble:(id)sender {
    for (NSNumber *display in self.desktopWindows) [self rethrowDisplay:display];
}

- (BOOL)validateMenuItem:(NSMenuItem *)item {
    if (item.action == @selector(rethrowMenuScreen:)) {
        return self.desktopWindows[item.representedObject].isVisible;
    }
    if (item.action == @selector(changePebble:)) {
        for (NSWindow *window in self.desktopWindows.allValues) {
            if (window.isVisible) return YES;
        }
        return NO;
    }
    return YES;
}

- (void)applyPauseTo:(WKWebView *)web {
    NSString *script = [NSString stringWithFormat:
        @"window.pebblePaused = %@; %@ document.dispatchEvent(new Event('visibilitychange'));",
        self.paused ? @"true" : @"false", self.smartPauseScript];
    [web evaluateJavaScript:script completionHandler:nil];
}

- (void)togglePause:(id)sender {
    // The switch has already flipped by the time it calls us; the menu item has not.
    self.paused = [sender isKindOfClass:NSSwitch.class] ?
        ((NSSwitch *)sender).state == NSControlStateValueOff : !self.paused;
    [NSUserDefaults.standardUserDefaults setBool:self.paused forKey:PausedPreference];
    self.pauseItem.state = self.paused ? NSControlStateValueOff : NSControlStateValueOn;
    [self syncSettingsControls];
    [self forEachRenderer:^(WKWebView *web) { [self applyPauseTo:web]; }];
}

- (void)quit:(id)sender {
    [NSApp terminate:sender];
}

- (void)webView:(WKWebView *)web decidePolicyForNavigationAction:(WKNavigationAction *)action
 decisionHandler:(void (^)(WKNavigationActionPolicy))reply {
    NSURL *page = [NSBundle.mainBundle URLForResource:@"wallpaper" withExtension:@"html"];
    reply([action.request.URL isEqual:page] ? WKNavigationActionPolicyAllow : WKNavigationActionPolicyCancel);
}

// Recover the same view so screen ownership, controls and the pass layout stay intact.
- (BOOL)prepareRendererForReload:(WKWebView *)web {
    NSString *config = nil;
    BOOL desktop = NO;
    for (NSNumber *display in self.desktopWindows) {
        if (self.desktopWindows[display].contentView != web) continue;
        desktop = YES;
        config = [self.rendererConfigScript stringByAppendingFormat:
            @"window.pebbleHistory = %@;%@window.pebblePaused = %@;",
            [self jsonForPebble:self.pebbleHistory[display.stringValue] ?: @{}],
            self.smartPauseScript, self.paused ? @"true" : @"false"];
        break;
    }
    if (web == self.passRenderer) config = self.passConfigScript;
    if (!config) return NO; // A disconnected display's delayed retry is obsolete.
    WKUserContentController *controller = web.configuration.userContentController;
    [controller removeAllUserScripts];
    if (desktop) config = [config stringByAppendingString:
        @"document.documentElement.classList.add('pebble-desktop');"];
    [controller addUserScript:[[WKUserScript alloc] initWithSource:config
        injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:YES]];
    return YES;
}

- (void)recoverRenderer:(WKWebView *)web error:(NSError *)error {
    PebbleRendererRecovery *state = [self.rendererRecovery objectForKey:web];
    if (!state || state.pending) return;
    if (state.attempts >= 3) {
        NSLog(@"Renderer recovery stopped after three attempts: %@. Use 恢复壁纸显示 to retry.", error);
        return;
    }
    state.pending = YES;
    NSUInteger generation = ++state.generation;
    NSTimeInterval delay = 1 << state.attempts++;
    NSLog(@"Renderer interrupted (%@); retry %lu in %.0fs.", error,
        (unsigned long)state.attempts, delay);
    __weak WKWebView *weakWeb = web;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(delay * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{
        WKWebView *view = weakWeb;
        if (!view || generation != state.generation) return;
        state.pending = NO;
        if (![self prepareRendererForReload:view]) return;
        NSURL *page = [NSBundle.mainBundle URLForResource:@"wallpaper" withExtension:@"html"];
        [view loadFileURL:page allowingReadAccessToURL:page];
    });
}

- (void)reloadRenderers:(id)sender {
    NSMutableArray *views = [NSMutableArray array];
    for (NSWindow *window in self.desktopWindows.allValues) [views addObject:window.contentView];
    if (self.passRenderer) [views addObject:self.passRenderer];
    for (WKWebView *web in views) {
        PebbleRendererRecovery *state = [self.rendererRecovery objectForKey:web];
        state.pending = NO;
        state.attempts = 0;
        state.generation++;
        [self recoverRenderer:web error:nil];
    }
}

- (void)webViewWebContentProcessDidTerminate:(WKWebView *)web {
    [self recoverRenderer:web error:[NSError errorWithDomain:WKErrorDomain
        code:WKErrorWebContentProcessTerminated userInfo:nil]];
}

- (void)webView:(WKWebView *)web didFailProvisionalNavigation:(WKNavigation *)navigation
    withError:(NSError *)error {
    if (error.code == NSURLErrorCancelled && [error.domain isEqual:NSURLErrorDomain]) return;
    [self recoverRenderer:web error:error];
}

- (void)webView:(WKWebView *)web didFailNavigation:(WKNavigation *)navigation withError:(NSError *)error {
    [self webView:web didFailProvisionalNavigation:navigation withError:error];
}

- (void)webView:(WKWebView *)web didFinishNavigation:(WKNavigation *)navigation {
    PebbleRendererRecovery *state = [self.rendererRecovery objectForKey:web];
    NSUInteger generation = state.generation;
    // A page that repeatedly loads then crashes must still exhaust its retry budget.
    __weak WKWebView *weakWeb = web;
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 60 * NSEC_PER_SEC),
                   dispatch_get_main_queue(), ^{
        if (weakWeb && state.generation == generation && !state.pending) state.attempts = 0;
    });
    [self applyPauseTo:web];
    if (self.verifyingRecovery && web == self.desktopWindows.allValues.firstObject.contentView) {
        [self checkRecoveredRenderer:web attempt:0];
    } else if (self.testPreviewPath && web == self.desktopWindows.allValues.firstObject.contentView) {
        [self verifyRenderer:web attempt:0];
    }
}

// A broken override still draws perfectly good stones, it just ignores the
// menu, so check every link: the saved choices reach the page, a choice pins
// what it promises, and clearing it lets the renderer vary again instead of
// leaving the last choice stuck.
- (void)verifyChoicesReachPage:(WKWebView *)web then:(void (^)(void))next {
    // The saved choices arrive through a document-start user script, a path no
    // amount of JavaScript testing covers. Check it before overwriting them.
    [web evaluateJavaScript:@"[window.pebbleConfig.texture, window.pebbleConfig.palette,"
                             " window.pebbleConfig.faces]"
          completionHandler:^(NSArray *injected, NSError *read) {
        NSArray *expected = @[self.texture ?: (id)NSNull.null, self.palette ?: (id)NSNull.null,
                              self.face ?: (id)NSNull.null];
        if (read || ![injected isKindOfClass:NSArray.class] || ![injected isEqualToArray:expected]) {
            NSLog(@"Saved choices %@ did not reach the page (got %@)", expected, injected);
            exit(7);
        }
        [self verifyOverrides:web then:next];
    }];
}

- (void)verifyOverrides:(WKWebView *)web then:(void (^)(void))next {
    NSString *script =
        @"(() => {const button = document.querySelector('button');"
         "const raise = count => Array.from({length: count}, () => {button.click();"
         " return {texture: window.pebbleTexture, palette: window.pebblePalette,"
         "         base: window.pebbleColors[0]};});"
         "const channels = stone => [1, 3, 5].map(at => parseInt(stone.base.substr(at, 2), 16));"
         "window.pebbleConfig.texture = 'rings'; window.pebbleConfig.palette = null;"
         "const ringed = raise(5);"
         "window.pebbleConfig.texture = null; window.pebbleConfig.palette = 'red';"
         "const reds = raise(5);"
         "window.pebbleConfig.palette = 'blue'; const blues = raise(5);"
         "window.pebbleConfig.palette = 'gray'; const greys = raise(5);"
         "window.pebbleConfig.palette = null; const free = raise(20);"
         // Only about a third of stones carry a face of their own, so compare
         // all three modes of the same stone and key the expectation off the
         // recovered seed rather than hoping the sample happens to cover both.
         "const canvas = document.querySelector('canvas');"
         "const shot = mode => {window.pebbleConfig.faces = mode;"
         " window.pebbleRedraw(); return canvas.toDataURL();};"
         "const faced = Array.from({length: 5}, () => {button.click();"
         " const seededFace = window.pebbleFaceRoll < .35;"
         " return {seededFace, seeded: shot(null), on: shot('on'), off: shot('off')};});"
         "window.pebbleConfig.faces = null; window.pebbleRedraw();"
         // A pinned seed has to reproduce the same stone, and clearing it has to
         // let the renderer wander again, or the pass would drift or be frozen.
         "window.pebbleConfig.seed = 123456;"
         "button.click(); const stampA = canvas.toDataURL();"
         "button.click(); const stampB = canvas.toDataURL();"
         "delete window.pebbleConfig.seed;"
         "button.click(); const looseA = canvas.toDataURL();"
         "button.click(); const looseB = canvas.toDataURL();"
         "const originalTilt = window.pebbleConfig.tiltDegrees;"
         "window.pebbleConfig.tiltDegrees = -30; window.pebbleRedraw();"
         "const tiltedLeft = canvas.toDataURL();"
         "window.pebbleConfig.tiltDegrees = 30; window.pebbleRedraw();"
         "const tiltedRight = canvas.toDataURL();"
         "window.pebbleConfig.tiltDegrees = originalTilt; window.pebbleRedraw();"
         "const originalRate = window.pebbleConfig.rotationRate, originalTimer = window.setInterval;"
         "let delay; window.setInterval = (callback, interval) => { delay = interval; return 0; };"
         "const schedule = rate => { delay = undefined; window.pebbleConfig.rotationRate = rate;"
         " document.dispatchEvent(new Event('visibilitychange')); return delay; };"
         "Object.defineProperty(document, 'hidden', {configurable:true, value:false});"
         "window.pebblePaused = false;"
         "const normal = schedule(1), slow = schedule(.5), fast = schedule(2);"
         "window.pebblePaused = true; const paused = schedule(2);"
         "window.pebblePaused = false; window.pebbleSmartPaused = true;"
         "const smartPaused = schedule(2); window.pebbleSmartPaused = false;"
         "const resumed = schedule(2); window.pebblePaused = true;"
         "const manuallyPaused = schedule(2);"
         "delete document.hidden; window.setInterval = originalTimer;"
         "window.pebbleConfig.rotationRate = originalRate;"
         "const restoredTiltFrame = canvas.toDataURL();"
         "window.pebbleHistory = {};"
         "Object.assign(window.pebbleConfig, {seed:111, texture:'rings', palette:'red', faces:'on'});"
         "window.pebbleThrow(); const saved = JSON.stringify(window.pebbleHistory.current);"
         "const savedFrame = canvas.toDataURL();"
         "Object.assign(window.pebbleConfig, {seed:222, texture:'stripes', palette:'blue', faces:'off'});"
         "window.pebbleThrow(); const second = JSON.stringify(window.pebbleHistory.current);"
         "window.pebblePrevious(); const previousMatches = canvas.toDataURL() === savedFrame"
         " && JSON.stringify(window.pebbleHistory.current) === saved"
         " && JSON.stringify(window.pebbleHistory.previous) === second;"
         "window.pebbleThrow(); window.pebbleRestore(JSON.parse(saved));"
         "const restoredMatches = canvas.toDataURL() === savedFrame"
         " && JSON.stringify(window.pebbleHistory.current) === saved;"
         "window.pebbleHistory = null;"
         "return {seedPinned: stampA === stampB, seedReleased: looseA !== looseB,"
         " previousMatches, restoredMatches,"
         " smartPause: smartPaused === undefined && resumed === fast && manuallyPaused === undefined,"
         " tiltApplied: tiltedLeft !== tiltedRight && looseB === restoredTiltFrame,"
         " speedApplied: normal > 0 && slow === normal * 2 && fast === normal / 2 && paused === undefined,"
         " facesForced: faced.every(stone => stone.on !== stone.off),"
         " facesMatchSeed: faced.every(stone =>"
         "   (stone.seeded !== stone.off) === stone.seededFace),"
         " texturePinned: ringed.every(stone => stone.texture === 'rings'),"
         " textureReleased: free.some(stone => stone.texture !== 'rings'),"
         " redIsWarm: reds.every(stone => {const [r, g, b] = channels(stone); return r > g && r > b;}),"
         " blueIsCool: blues.every(stone => {const [r, g, b] = channels(stone); return b > r && b > g;}),"
         " greyIsNeutral: greys.every(stone => {const [r, g, b] = channels(stone); return r === g && g === b;}),"
         " familyVaries: new Set(reds.map(stone => stone.base)).size > 1,"
         " paletteTagged: reds.every(stone => stone.palette === 'red'),"
         " paletteReleased: free.every(stone => stone.palette === null)};})()";
    [web evaluateJavaScript:script completionHandler:^(NSDictionary *result, NSError *error) {
        if (error || ![result isKindOfClass:NSDictionary.class]) {
            NSLog(@"Could not check the renderer overrides: %@", error);
            exit(6);
        }
        NSMutableArray<NSString *> *failed = [NSMutableArray array];
        for (NSString *check in result) {
            if (![result[check] boolValue]) [failed addObject:check];
        }
        if (failed.count) {
            NSLog(@"Renderer overrides failed: %@", [failed componentsJoinedByString:@", "]);
            exit(6);
        }
        next();
    }];
}

- (void)verifyBackgroundPicker:(WKWebView *)web then:(void (^)(void))next {
    [self backgroundPicker];
    NSString *original = self.backgroundPreset;
    [web callAsyncJavaScript:
        @"const frame = () => { window.pebbleRedraw(); return document.querySelector('canvas').toDataURL(); };"
         "return {preset: document.documentElement.dataset.pebbleBackground, frame: frame()};"
        arguments:@{} inFrame:nil inContentWorld:WKContentWorld.pageWorld
        completionHandler:^(NSDictionary *before, NSError *error) {
            if (error || ![before[@"preset"] isEqual:original]) exit(8);
            [self verifyBackgroundAtIndex:0 initialFrame:before[@"frame"] web:web then:^{
                for (NSButton *choice in self.backgroundButtons) {
                    if ([original isEqual:@(BackgroundKeys[choice.tag])]) {
                        [choice performClick:nil];
                        break;
                    }
                }
                NSLog(@"All four solid backgrounds applied without replacing the stone.");
                next();
            }];
        }];
}

- (void)verifyBackgroundAtIndex:(NSUInteger)index initialFrame:(NSString *)frame
                            web:(WKWebView *)web then:(void (^)(void))next {
    if (index == BackgroundCount) {
        next();
        return;
    }
    [self.backgroundButtons[index] performClick:nil];
    NSString *read = @"window.pebbleRedraw(); ({frame: document.querySelector('canvas').toDataURL(),"
                     "preset: document.documentElement.dataset.pebbleBackground,"
                     "color: getComputedStyle(document.body).backgroundColor})";
    [web evaluateJavaScript:read completionHandler:^(NSDictionary *result, NSError *error) {
        NSUInteger rgb = BackgroundColors[index];
        NSString *color = [NSString stringWithFormat:@"rgb(%lu, %lu, %lu)",
            (unsigned long)((rgb >> 16) & 255), (unsigned long)((rgb >> 8) & 255), (unsigned long)(rgb & 255)];
        if (error || ![result[@"preset"] isEqual:@(BackgroundKeys[index])] ||
            ![result[@"color"] isEqual:color] || ![result[@"frame"] isEqual:frame]) exit(8);
        [self verifyBackgroundAtIndex:index + 1 initialFrame:frame web:web then:next];
    }];
}

- (void)verifyPhoneWallpaperSizes:(WKWebView *)web {
    NSMutableArray *sizes = [NSMutableArray array];
    for (NSUInteger index = 1; index < WallpaperSizeCount; index++) {
        [sizes addObject:@[@(WallpaperSizes[index].width), @(WallpaperSizes[index].height)]];
    }
    [web callAsyncJavaScript:
        @"for (const [width, height] of sizes) {"
         " const image = new Image();"
         " image.src = 'data:image/png;base64,' + window.pebbleExport(width, height);"
         " await image.decode();"
         " if (image.naturalWidth !== width || image.naturalHeight !== height) return false;"
         "} return true;"
        arguments:@{@"sizes":sizes} inFrame:nil inContentWorld:WKContentWorld.pageWorld
        completionHandler:^(NSNumber *verified, NSError *error) {
            if (error || !verified.boolValue) {
                NSLog(@"Phone wallpaper size verification failed: %@", error);
                exit(9);
            }
            NSLog(@"Verified native PNG dimensions for all five iPhone export sizes.");
            [self verifyRendererRecovery:web];
        }];
}

// Exercise the production recovery path with the latest native settings, rather
// than merely checking that a delegate method exists. --verify never alters history.
- (void)verifyRendererRecovery:(WKWebView *)web {
    // Verification normally omits persistence; give the page an explicit stone.
    [web evaluateJavaScript:
        @"window.pebbleHistory={};window.pebbleThrow();window.pebbleHistory"
        completionHandler:^(NSDictionary *saved, NSError *readError) {
        if (readError || !saved[@"current"]) exit(10);
        NSNumber *display = web.window.screen.deviceDescription[@"NSScreenNumber"];
        self.pebbleHistory[display.stringValue] = saved;
        self.recoveryExpectedHistory = saved;
        self.tiltDegrees = 17;
        self.rotationRate = 1.5;
        self.paused = YES;
        self.verifyingRecovery = YES;
        [self webView:web didFailProvisionalNavigation:nil withError:
            [NSError errorWithDomain:NSURLErrorDomain code:NSURLErrorCancelled userInfo:nil]];
        if ([self.rendererRecovery objectForKey:web].attempts != 0) exit(10);
        [self webViewWebContentProcessDidTerminate:web];
        // Duplicate failures must coalesce into one pending retry.
        [self webView:web didFailNavigation:nil withError:
            [NSError errorWithDomain:NSURLErrorDomain code:NSURLErrorCannotConnectToHost userInfo:nil]];
        if ([self.rendererRecovery objectForKey:web].attempts != 1) exit(10);
    }];
}

- (void)checkRecoveredRenderer:(WKWebView *)web attempt:(NSUInteger)attempt {
    [web evaluateJavaScript:
        @"window.pebbleRedraw?.();({history:window.pebbleHistory,tilt:window.pebbleConfig.tiltDegrees,"
         "rate:window.pebbleConfig.rotationRate,paused:window.pebblePaused,"
         "ready:typeof window.pebbleTone==='number' && typeof window.pebbleThrow==='function'})"
        completionHandler:^(NSDictionary *result, NSError *error) {
        if (error || ![result[@"ready"] boolValue]) {
            if (attempt >= 40) exit(10);
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 150 * NSEC_PER_MSEC),
                dispatch_get_main_queue(), ^{ [self checkRecoveredRenderer:web attempt:attempt + 1]; });
            return;
        }
        if (![result[@"history"] isEqual:self.recoveryExpectedHistory] ||
            [result[@"tilt"] integerValue] != 17 || [result[@"rate"] doubleValue] != 1.5 ||
            ![result[@"paused"] boolValue]) {
            NSLog(@"Recovered renderer lost state: %@", result); exit(10);
        }
        if (self.recoveryVerificationStage++ == 0) {
            [self webView:web didFailProvisionalNavigation:nil withError:
                [NSError errorWithDomain:NSURLErrorDomain code:NSURLErrorCannotOpenFile userInfo:nil]];
            return;
        }
        PebbleRendererRecovery *state = [self.rendererRecovery objectForKey:web];
        if (self.recoveryVerificationStage == 3) {
            if (state.attempts != 1) exit(10);
            NSLog(@"Renderer recovery preserved stone/settings; cancellation, retry limit and manual retry verified.");
#if __has_include(<Sparkle/Sparkle.h>)
            [self verifyUpdateCallbackContract];
#else
            [NSApp terminate:nil];
#endif
            return;
        }
        state.attempts = 3;
        [self webViewWebContentProcessDidTerminate:web];
        if (state.pending || state.attempts != 3) exit(10);
        [self reloadRenderers:nil];
    }];
}

#if __has_include(<Sparkle/Sparkle.h>)
- (void)verifyUpdateCallbackContract {
    __block NSUInteger installs = 0;
    [self stageUpdateInstallation:^{ installs++; }];
    if (installs != 0) exit(11); // The delegate must return before invoking Sparkle.
    dispatch_async(dispatch_get_main_queue(), ^{
        if (installs != 1 || !self.pendingInstall) exit(11);
        [self installPendingUpdateIfIdle];
        if (installs != 1) exit(11); // Coalesce duplicate close/idle notifications.
        [self resetPendingUpdate];
        if (self.pendingInstall || self.installationRequested) exit(11);
        [self stageUpdateInstallation:^{ installs++; }];
        dispatch_async(dispatch_get_main_queue(), ^{
            if (installs != 2) exit(11);
            [self resetPendingUpdate];
            if (self.pendingInstall || self.installationRequested) exit(11);
            NSLog(@"Update callback ordering, duplicate suppression and failed-cycle cleanup verified.");
            [NSApp terminate:nil];
        });
    });
}
#endif

- (void)verifyRenderer:(WKWebView *)web attempt:(NSUInteger)attempt {
    // Each draw clears the canvas. A nontransparent center confirms the offline texture rendered.
    NSString *readCanvas =
        @"(() => {const c = document.querySelector('canvas');"
         "if (!c || c.width !== c.height) return '';"
         "const gl = c.getContext('webgl'), pixel = new Uint8Array(4);"
         "gl.readPixels(c.width/2,c.height/2,1,1,gl.RGBA,gl.UNSIGNED_BYTE,pixel);"
         "return pixel[3] && typeof window.pebbleTone === 'number'"
         " ? {image:c.toDataURL(),tone:window.pebbleTone} : null;})()";
    NSString *pauseAndReadCanvas =
        [@"window.pebblePaused=true; document.dispatchEvent(new Event('visibilitychange'));"
         stringByAppendingString:readCanvas];
    [web evaluateJavaScript:pauseAndReadCanvas completionHandler:^(NSDictionary *first, NSError *error) {
        if (error || ![first isKindOfClass:NSDictionary.class]) {
            if (attempt >= 40) {
                NSLog(@"Wallpaper canvas did not render: %@", error);
                exit(1);
            }
            dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 150 * NSEC_PER_MSEC),
                           dispatch_get_main_queue(), ^{ [self verifyRenderer:web attempt:attempt + 1]; });
            return;
        }
        NSNumber *display = web.window.screen.deviceDescription[@"NSScreenNumber"];
        NSPanel *panel = display ? self.desktopControls[display] : nil;
        NSButton *button = (NSButton *)panel.contentView;
        if (!panel.isVisible || !button.isEnabled) exit(2);
        [button performClick:nil];
        [web evaluateJavaScript:readCanvas completionHandler:^(NSDictionary *second, NSError *readError) {
            if (readError || ![second isKindOfClass:NSDictionary.class] ||
                [first[@"image"] isEqual:second[@"image"]]) exit(2);
            NSColor *tint = [button.contentTintColor colorUsingColorSpace:NSColorSpace.sRGBColorSpace];
            NSUInteger buttonTone = (lround(tint.redComponent * 255) << 16) |
                                    (lround(tint.greenComponent * 255) << 8) |
                                     lround(tint.blueComponent * 255);
            if (tint.alphaComponent != 1 || buttonTone != [second[@"tone"] unsignedIntegerValue]) exit(5);
            WKSnapshotConfiguration *configuration = [WKSnapshotConfiguration new];
            configuration.snapshotWidth = @1280;
            [web takeSnapshotWithConfiguration:configuration completionHandler:^(NSImage *image, NSError *snapshotError) {
                if (!image || snapshotError) exit(3);
                NSBitmapImageRep *buttonBitmap = [button bitmapImageRepForCachingDisplayInRect:button.bounds];
                [button cacheDisplayInRect:button.bounds toBitmapImageRep:buttonBitmap];
                NSImage *buttonImage = [[NSImage alloc] initWithSize:button.bounds.size];
                [buttonImage addRepresentation:buttonBitmap];

                NSRect desktopFrame = web.window.frame;
                CGFloat scale = image.size.width / NSWidth(desktopFrame);
                NSRect buttonRect = NSMakeRect((NSMinX(panel.frame) - NSMinX(desktopFrame)) * scale,
                                               (NSMinY(panel.frame) - NSMinY(desktopFrame)) * scale,
                                               NSWidth(panel.frame) * scale, NSHeight(panel.frame) * scale);
                NSImage *desktopPreview = [[NSImage alloc] initWithSize:image.size];
                [desktopPreview lockFocus];
                [image drawAtPoint:NSZeroPoint fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
                [buttonImage drawInRect:buttonRect fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
                [desktopPreview unlockFocus];
                NSBitmapImageRep *bitmap = [[NSBitmapImageRep alloc] initWithData:desktopPreview.TIFFRepresentation];
                NSData *png = [bitmap representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
                if (![png writeToFile:self.testPreviewPath atomically:YES]) exit(4);
                [self verifyChoicesReachPage:web then:^{
                    [self verifyBackgroundPicker:web then:^{
                        NSLog(@"Offline rendering, desktop button, matching text colors and "
                              "pinned texture and colour families verified.");
                        [web evaluateJavaScript:@"window.pebbleExport(3840,2160)" completionHandler:^(id encoded, NSError *error) {
                            NSData *png = [self wallpaperPNGFromBase64:encoded size:WallpaperSizes[0]];
                            NSBitmapImageRep *image = png ? [NSBitmapImageRep imageRepWithData:png] : nil;
                            NSColor *corner = [image colorAtX:0 y:0];
                            NSColor *center = [image colorAtX:1920 y:1080];
                            NSString *sample = [[self.testPreviewPath stringByDeletingLastPathComponent]
                                stringByAppendingPathComponent:@"wallpaper-4k-verification.png"];
                            if (error || !png || !center || [center isEqual:corner] ||
                                ![png writeToFile:sample atomically:YES]) {
                                NSLog(@"4K wallpaper render failed: %@", error);
                                exit(9);
                            }
                            NSLog(@"Verified 3840 × 2160 PNG with rendered stone and solid background.");
                            [self verifyPhoneWallpaperSizes:web];
                        }];
                    }];
                }];
            }];
        }];
    }];
}

@end

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        NSApplication *application = NSApplication.sharedApplication;
        PebbleApp *delegate = [PebbleApp new];
        if (argc == 3 && strcmp(argv[1], "--verify") == 0) {
            delegate.testPreviewPath = @(argv[2]);
        }
        if (argc >= 4 && strcmp(argv[1], "--shoot") == 0) {
            delegate.shotPath = @(argv[2]);
            delegate.shotSection = atoi(argv[3]);
            if (argc == 5) delegate.shotPassNumber = atoi(argv[4]);
        }
        application.delegate = delegate;
        [application run];
    }
    return 0;
}
